using namespace std;

int main() {
    string s;
    cin >> s;
    const long long MOD = 1000000007;
    long long answer = 0;
    // Every length-5 palindrome has the form abcba: 8 patterns.
    for (int mask = 0; mask < 8; mask++) {
        char a = '0' + (mask >> 2 & 1), b = '0' + (mask >> 1 & 1), c = '0' + (mask & 1);
        char pattern[5] = {a, b, c, b, a};
        long long dp[6] = {1, 0, 0, 0, 0, 0};
        for (char ch : s)
            for (int j = 5; j >= 1; j--)
                if (ch == pattern[j - 1]) dp[j] = (dp[j] + dp[j - 1]) % MOD;
        answer = (answer + dp[5]) % MOD;
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        final long MOD = 1_000_000_007L;
        long answer = 0;
        // Every length-5 palindrome has the form abcba: 8 patterns.
        for (int mask = 0; mask < 8; mask++) {
            char a = (char) ('0' + (mask >> 2 & 1)), b = (char) ('0' + (mask >> 1 & 1)), c = (char) ('0' + (mask & 1));
            char[] pattern = {a, b, c, b, a};
            long[] dp = {1, 0, 0, 0, 0, 0};
            for (int i = 0; i < s.length(); i++) {
                char ch = s.charAt(i);
                for (int j = 5; j >= 1; j--)
                    if (ch == pattern[j - 1]) dp[j] = (dp[j] + dp[j - 1]) % MOD;
            }
            answer = (answer + dp[5]) % MOD;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := token()
	const mod = 1000000007
	answer := 0
	// Every length-5 palindrome has the form abcba: 8 patterns.
	for mask := 0; mask < 8; mask++ {
		a, b, c := byte('0'+(mask>>2&1)), byte('0'+(mask>>1&1)), byte('0'+(mask&1))
		pattern := [5]byte{a, b, c, b, a}
		dp := [6]int{1}
		for _, ch := range s {
			for j := 5; j >= 1; j-- {
				if ch == pattern[j-1] {
					dp[j] = (dp[j] + dp[j-1]) % mod
				}
			}
		}
		answer = (answer + dp[5]) % mod
	}
	fmt.Println(answer)
}
